import { Canvas } from '@react-three/fiber';
import { useTexture } from '@react-three/drei';

function TexturedBox() {
  // useTexture loads multiple textures in parallel and returns an array
  // Each texture is automatically optimized and cached by drei
  const [diffuse, normal, roughness] = useTexture([
    '/textures/diffuse.jpg',    // Base color/albedo texture
    '/textures/normal.jpg',     // Normal map adds surface detail
    '/textures/roughness.jpg'   // Roughness map controls shininess
  ]);

  return (
    <mesh>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial 
        map={diffuse}           // Base color texture
        normalMap={normal}      // Surface detail (bumps, scratches)
        roughnessMap={roughness} // Material variation (matte vs glossy)
      />
    </mesh>
  );
}

