import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import * as THREE from 'three';

function VerticesExample() {
  // Extract vertex positions from a cylinder geometry
  // This demonstrates how 3D shapes are built from points in space
  const pointsGeometry = useMemo(() => {
    // Create a cylinder geometry (beer can shape)
    const geometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);

    // Get the position attribute array (all vertex coordinates)
    const positions = geometry.attributes.position.array;

    // Create a new BufferGeometry to hold just the points
    const bufferGeometry = new THREE.BufferGeometry();

    // Set the position attribute (3 components per vertex: x, y, z)
    bufferGeometry.setAttribute(
      'position',
      new THREE.Float32BufferAttribute(positions, 3)
    );

    return bufferGeometry;
  }, []);

  return (
    <Canvas>
      {/* points renders vertices as individual dots */}
      <points geometry={pointsGeometry}>
        {/* pointsMaterial controls how vertices are displayed */}
        <pointsMaterial 
          size={0.05}        // Size of each point
          color="#10b981"    // Green color
          sizeAttenuation    // Points get smaller with distance
        />
      </points>
    </Canvas>
  );
}

export default VerticesExample;

import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { Edges } from '@react-three/drei';
import * as THREE from 'three';

function EdgesExample() {
  // Create cylinder geometry: radiusTop, radiusBottom, height, radialSegments
  // useMemo ensures geometry is only created once (performance)
  const canGeometry = useMemo(() => {
    return new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
  }, []);

  return (
    <Canvas>
      <mesh geometry={canGeometry}>
        {/* 
          Transparent material makes the mesh invisible.
          We only want to see the edges, not the faces.
        */}
        <meshBasicMaterial transparent opacity={0} />
        {/* 
          Edges component from drei draws wireframe lines.
          threshold={0} means draw all edges (no angle filtering).
        */}
        <Edges color="#3b82f6" threshold={0} />
      </mesh>
    </Canvas>
  );
}

export default EdgesExample;

