import { useLayoutEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { useGLTF } from '@react-three/drei';
import { useTexture } from '@react-three/drei';
import * as THREE from 'three';

function BeerCan({ texturePath }: { texturePath: string }) {
  // useGLTF loads and caches the 3D model
  const { scene } = useGLTF('/beer2.gltf');
  // useTexture loads and caches the texture image
  const texture = useTexture(texturePath);

  // Apply texture to materials before render (useLayoutEffect runs synchronously)
  useLayoutEffect(() => {
    // Traverse the scene graph to find all meshes
    scene.traverse((obj) => {
      // Check if object is a mesh with a material
      if (obj instanceof THREE.Mesh && obj.material) {
        const material = obj.material;

        // Handle both single materials and material arrays
        if (Array.isArray(material)) {
          // Apply texture to first material (usually the main material)
          const mainMaterial = material[0];
          if (mainMaterial instanceof THREE.MeshStandardMaterial) {
            mainMaterial.map = texture;
            mainMaterial.needsUpdate = true;
          }
        } else if (material instanceof THREE.MeshStandardMaterial) {
          // Apply texture to single material
          material.map = texture;
          material.needsUpdate = true;
        }
      }
    });
  }, [scene, texture]);

  // primitive renders the loaded GLTF scene as-is
  return <primitive object={scene} />;
}

function Scene({ texturePath }: { texturePath: string }) {
  return (
    <Canvas>
      <BeerCan texturePath={texturePath} />
      {/* Ambient light provides base illumination */}
      <ambientLight intensity={0.4} />
      {/* Primary directional light from top-right */}
      <directionalLight position={[8, 12, 6]} intensity={1.2} />
      {/* Rim light from behind for depth and separation */}
      <directionalLight position={[-5, 5, -5]} intensity={0.6} />
    </Canvas>
  );
}

export default Scene;
